    static JdbcTemplate db;SharedCarrierService service;OrderCatalog catalog;String company;
    static Map<String,Object> row(Object...args){Map<String,Object> out=new LinkedHashMap<>();for(int n=0;n<args.length;n+=2)out.put(String.valueOf(args[n]),args[n+1]);return out;}
    @BeforeAll static void database(){String url=System.getenv("CARRIER_TEST_URL");assertNotNull(url,"Disposable carrier database required");db=new JdbcTemplate(new DriverManagerDataSource(url,"root",System.getenv("INVENTORY_TEST_PASSWORD")));}
    @BeforeEach void setup(){company="TEST_"+token().substring(0,16);OrderRepository repository=new OrderRepository();ReflectionTestUtils.setField(repository,"jdbc",db);service=new SharedCarrierService(repository);catalog=mock(OrderCatalog.class);ReflectionTestUtils.setField(service,"catalog",catalog);when(catalog.carrierContext(company)).thenReturn(row("connections",Arrays.asList(row("id",1,"provider","QIMEN"),row("id",2,"provider","QIMEN")),"stores",Arrays.asList(row("connection_id",1,"owner_code","O1","real_store_code","R1"),row("connection_id",2,"owner_code","O1","real_store_code","R1"))));when(catalog.channels(company)).thenReturn(Arrays.asList(row("channel_id",7,"channel_type","TM","connection_id","10")));}
    Map<String,Object> standard(String code){return service.save(company,"standard",row("revision",0,"standard_code",code,"standard_name",code,"aliases",Arrays.asList("别名"+code),"category","EXPRESS","enabled",1),"tester");}
    Map<String,Object> ctx(String system,String purpose,String code){return row("system_type",system,"provider","WMS".equals(system)?"QIMEN":"TMALL","purpose",purpose,"connection_id","WMS".equals(system)?"1":"","shop_id","","owner_code","","real_store_code","","direction","IN","external_code",code);}
    Map<String,Object> mapping(Map<String,Object> scope,long carrier,String code,String direction,int def,String product){Map<String,Object> d=new LinkedHashMap<>(scope);d.putAll(row("revision",0,"external_code",code,"external_name","目录 "+code,"enabled",1,"evidence","TEST source"));d=service.save(company,"directory",d,"tester");Map<String,Object> m=new LinkedHashMap<>(scope);m.putAll(row("revision",0,"standard_id",carrier,"directory_id",d.get("id"),"direction",direction,"is_default",def,"product_code",product,"enabled",1,"evidence","TEST confirmed"));return service.save(company,"mapping",m,"tester");}
    void cap(long standard,String flow,List<String> deny){service.save(company,"capability",row("revision",0,"connection_id","1","owner_code","O1","real_store_code","R1","standard_id",standard,"flow",flow,"product_code","","provinces",Collections.emptyList(),"excluded_provinces",deny,"enabled",1,"evidence","TEST warehouse"),"tester");}
    @Test void stableIdentityTenantIsolationAliasSearchAndIndependentActivation(){Map<String,Object>s=standard("TEST_SF");assertEquals(1,number(s,"enabled"));assertThrows(RuntimeException.class,()->standard("TEST_SF"));assertEquals(1,((List<?>)service.page(company,"standard",Collections.singletonMap("keyword","别名TEST")).get("rows")).size());assertTrue(((List<?>)service.page("OTHER","standard",Collections.emptyMap()).get("rows")).isEmpty());s.put("standard_code","CHANGED");assertThrows(IllegalArgumentException.class,()->service.save(company,"standard",s,"tester"));}
    @Test void caseLeadingZeroPunctuationAndWmsConnectionAreExact(){long a=number(standard("A"),"id"),b=number(standard("B"),"id");Map<String,Object> scope=ctx("WMS","WMS_OUTBOUND_ACTUAL","");mapping(scope,a,"001/sF.a","IN",0,"");mapping(scope,b,"001/SF.a","IN",0,"");assertEquals(a,number(service.convert(company,ctx("WMS","WMS_OUTBOUND_ACTUAL","001/sF.a")),"standard_id"));assertEquals("MISSING",service.convert(company,ctx("WMS","WMS_OUTBOUND_ACTUAL","1/sF.a")).get("state"));Map<String,Object> other=ctx("WMS","WMS_OUTBOUND_ACTUAL","001/sF.a");other.put("connection_id","2");assertEquals("MISSING",service.convert(company,other).get("state"));mapping(other,b,"001/sF.a","IN",0,"");assertEquals(b,number(service.convert(company,other),"standard_id"));}
    @Test void shopDisabledScopeShadowsPlatformWithoutFallback(){long a=number(standard("A"),"id");Map<String,Object> p=ctx("CHANNEL","CHANNEL_RETURN_IDENTIFY","");mapping(p,a,"TEST-001","IN",0,"");Map<String,Object> shop=new LinkedHashMap<>(p);shop.put("shop_id","7");Map<String,Object> m=mapping(shop,a,"TEST-001","IN",0,"");m.put("enabled",0);m.put("disabled_reason","TEST暂停");service.save(company,"mapping",m,"tester");shop.put("external_code","TEST-001");assertEquals("DISABLED",service.convert(company,shop).get("state"));assertEquals("RESOLVED",service.convert(company,ctx("CHANNEL","CHANNEL_RETURN_IDENTIFY","TEST-001")).get("state"));}
    @Test void ownerWarehousePriorityAndPurposeIsolation(){long a=number(standard("A"),"id"),b=number(standard("B"),"id");Map<String,Object> base=ctx("WMS","WMS_OUTBOUND_ACTUAL","");mapping(base,a,"TEST-X","IN",0,"");Map<String,Object> owner=new LinkedHashMap<>(base);owner.put("owner_code","O1");mapping(owner,b,"TEST-X","IN",0,"");owner.put("external_code","TEST-X");assertEquals(b,number(service.convert(company,owner),"standard_id"));Map<String,Object> real=new LinkedHashMap<>(owner);real.put("real_store_code","R1");Map<String,Object> m=mapping(real,a,"TEST-X","IN",0,"");m.put("enabled",0);m.put("disabled_reason","暂停");service.save(company,"mapping",m,"tester");assertEquals("DISABLED",service.convert(company,real).get("state"));real.put("purpose","WMS_RETURN_ACTUAL");assertEquals("MISSING",service.convert(company,real).get("state"));}
    @Test void inputAliasesAndOutputChoicesAreIndependentActions(){long a=number(standard("A"),"id");Map<String,Object> source=ctx("CHANNEL","CHANNEL_RETURN_IDENTIFY","");mapping(source,a,"TEST-X","BOTH",0,"");mapping(source,a,"TEST-Y","BOTH",0,"");assertEquals(a,number(service.convert(company,ctx("CHANNEL","CHANNEL_RETURN_IDENTIFY","TEST-Y")),"standard_id"));Map<String,Object> scope=ctx("CHANNEL","CHANNEL_SHIPPING","");mapping(scope,a,"TEST-X","OUT",0,"");Map<String,Object> m=mapping(scope,a,"TEST-Y","OUT",0,"");Map<String,Object> target=new LinkedHashMap<>(scope);target.putAll(row("direction","OUT","standard_id",a));assertEquals("CONFLICT",service.convert(company,target).get("state"));m.put("is_default",1);service.save(company,"mapping",m,"tester");assertEquals("TEST-Y",service.convert(company,target).get("external_code"));}
    @Test void productSelectionAndDisabledProductCannotFallback(){long a=number(standard("A"),"id");Map<String,Object> scope=ctx("CHANNEL","CHANNEL_SHIPPING","");mapping(scope,a,"TEST-default","OUT",1,"");Map<String,Object> fast=mapping(scope,a,"TEST-fast","OUT",0,"FAST");Map<String,Object> out=new LinkedHashMap<>(scope);out.putAll(row("standard_id",a,"direction","OUT","product_code","FAST"));assertEquals("TEST-fast",service.convert(company,out).get("external_code"));fast.put("enabled",0);fast.put("disabled_reason","产品暂停");service.save(company,"mapping",fast,"tester");assertEquals("DISABLED",service.convert(company,out).get("state"));}
    @Test void outboundRegionDoesNotRestrictInboundOrRequireChannelMapping(){long a=number(standard("A"),"id");Map<String,Object> out=ctx("WMS","WMS_OUTBOUND_CREATE","");mapping(out,a,"TEST-OUT","OUT",1,"");Map<String,Object> in=ctx("WMS","WMS_RETURN_CREATE","");mapping(in,a,"TEST-IN","OUT",1,"");cap(a,"OUTBOUND",Arrays.asList("上海"));cap(a,"INBOUND",Collections.emptyList());for(Map<String,Object> c:Arrays.asList(out,in))c.putAll(row("standard_id",a,"direction","OUT","owner_code","O1","real_store_code","R1","province","上海"));assertEquals("CAPABILITY_UNSUPPORTED",service.convert(company,out).get("state"));assertEquals("TEST-IN",service.convert(company,in).get("external_code"));out.put("province","北京");assertEquals("TEST-OUT",service.convert(company,out).get("external_code"));}
    @Test void immutableRetryUsesOriginalCodeAfterMappingDisabled(){long a=number(standard("A"),"id");Map<String,Object> scope=ctx("CHANNEL","CHANNEL_SHIPPING","");Map<String,Object> m=mapping(scope,a,"TEST-001","OUT",1,"");Map<String,Object> out=new LinkedHashMap<>(scope);out.putAll(row("standard_id",a,"direction","OUT"));Map<String,Object> first=service.freeze(company,"TEST_REQUEST",out,"tester");m.putAll(row("enabled",0,"disabled_reason","变更"));service.save(company,"mapping",m,"tester");assertEquals(encode(first),encode(service.freeze(company,"TEST_REQUEST",out,"tester")));out.put("standard_id",a+1);assertThrows(IllegalArgumentException.class,()->service.freeze(company,"TEST_REQUEST",out,"tester"));}
    @Test void importPreviewErrorsPreventWritesAndConfirmationIsIdempotent(){Map<String,Object> input=ctx("CHANNEL","CHANNEL_SHIPPING","");input.putAll(row("evidence","TEST source","rows",Arrays.asList(row("external_code","001.Sf","external_name","Name","enabled",1),row("external_code","001.Sf","external_name","Duplicate","enabled",1),row("external_code","X","external_name","","enabled",1))));Map<String,Object> bad=service.importPreview(company,input,"tester");assertEquals(2,number(bad,"errors"));assertThrows(IllegalArgumentException.class,()->service.importConfirm(company,text(bad,"request_key"),"tester"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM oms_carrier_directory WHERE company_code=?",Integer.class,company));input.put("rows",Arrays.asList(row("external_code","001.Sf","external_name","Name","enabled",1)));Map<String,Object> good=service.importPreview(company,input,"tester");assertThrows(IllegalArgumentException.class,()->service.importConfirm(company,text(good,"request_key"),"other"));service.importConfirm(company,text(good,"request_key"),"tester");service.importConfirm(company,text(good,"request_key"),"tester");assertEquals("001.Sf",db.queryForObject("SELECT external_code FROM oms_carrier_directory WHERE company_code=?",String.class,company));}
    @Test void concurrentSavesHaveOneWinner() throws Exception {Map<String,Object>s=standard("A");ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Boolean>> tasks=new ArrayList<>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{start.await();try{service.save(company,"standard",new LinkedHashMap<>(s),"parallel");return true;}catch(IllegalArgumentException stale){return false;}}));start.countDown();int wins=0;for(Future<Boolean> task:tasks)if(task.get(10,TimeUnit.SECONDS))wins++;assertEquals(1,wins);}finally{pool.shutdownNow();}}
    @Test void todoDeduplicationUsesParcelNotWaybillAndRepairDoesNotCompleteBusiness(){Map<String,Object> ctx=ctx("CHANNEL","CHANNEL_RETURN_IDENTIFY","TEST-X"),fact=row("business_type","SHIPMENT","business_id",1,"business_sn","TEST-SHIP","fact_id","P1","blocked_action","PLATFORM_SHIPPING");Map<String,Object> missing=service.convert(company,ctx);long id=service.issue(company,fact,ctx,missing,"tester");assertEquals(id,service.issue(company,fact,ctx,missing,"tester"));fact.put("fact_id","P2");assertNotEquals(id,service.issue(company,fact,ctx,missing,"tester"));long a=number(standard("A"),"id");mapping(ctx,a,"TEST-X","IN",0,"");assertEquals("RESOLVED",service.revalidate(company,id,number(service.todo(company,id),"revision"),"tester").get("state"));assertEquals("READY",service.todo(company,id).get("state"));}
    @Test void ambiguousResolverNeverPicksFirst(){Map<String,Object> ctx=ctx("CHANNEL","CHANNEL_RETURN_IDENTIFY","TEST-X"),a=new LinkedHashMap<>(ctx);a.putAll(row("id",1,"standard_id",1,"enabled",1,"standard_enabled",1,"directory_enabled",1));Map<String,Object>b=new LinkedHashMap<>(a);b.putAll(row("id",2,"standard_id",2));assertEquals("CONFLICT",CarrierResolver.convert(ctx,Arrays.asList(a,b)).get("state"));}
    @Test void batchPreviewRequiresHumanSelectionAndConfirmationHasAuditAndIdempotency(){long a=number(standard("A"),"id");Map<String,Object> scope=ctx("CHANNEL","CHANNEL_RETURN_IDENTIFY","");Map<String,Object> directory=new LinkedHashMap<>(scope);directory.putAll(row("revision",0,"enabled",1,"external_code","TEST-BATCH-001","external_name","A","evidence","TEST official directory"));Map<String,Object> d=service.save(company,"directory",directory,"tester");List<Map<String,Object>> suggestions=service.suggestions(company,Arrays.asList(number(d,"id")));assertFalse(((List<?>)suggestions.get(0).get("candidates")).isEmpty());Map<String,Object> batch=new LinkedHashMap<>(scope);batch.putAll(row("evidence","TEST human choice","rows",Arrays.asList(row("directory_id",d.get("id"),"standard_id",a,"direction","IN","is_default",0,"enabled",1,"product_code",""))));Map<String,Object> preview=service.mappingPreview(company,batch,"tester");assertEquals(0,number(preview,"errors"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM oms_carrier_mapping WHERE company_code=?",Integer.class,company));service.mappingConfirm(company,text(preview,"request_key"),"tester");service.mappingConfirm(company,text(preview,"request_key"),"tester");assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_carrier_mapping WHERE company_code=?",Integer.class,company));assertEquals(a,number(service.convert(company,ctx("CHANNEL","CHANNEL_RETURN_IDENTIFY","TEST-BATCH-001")),"standard_id"));assertThrows(IllegalArgumentException.class,()->service.importConfirm(company,text(preview,"request_key"),"tester"));}
    @Test void numericDirectoryCodeAndConflictingBatchCannotBecomeFormalMappings(){long a=number(standard("A"),"id");Map<String,Object> scope=ctx("CHANNEL","CHANNEL_SHIPPING","");Map<String,Object> d=new LinkedHashMap<>(scope);d.putAll(row("revision",0,"enabled",1,"external_code",1,"external_name","TEST","evidence","TEST"));assertThrows(IllegalArgumentException.class,()->service.save(company,"directory",d,"tester"));d.put("external_code","001");Map<String,Object> saved=service.save(company,"directory",d,"tester");Map<String,Object> r=row("directory_id",saved.get("id"),"standard_id",a,"direction","BOTH","is_default",1,"enabled",1,"product_code","");Map<String,Object> input=new LinkedHashMap<>(scope);input.putAll(row("evidence","TEST","rows",Arrays.asList(r,r)));Map<String,Object> preview=service.mappingPreview(company,input,"tester");assertEquals(1,number(preview,"errors"));assertThrows(IllegalArgumentException.class,()->service.mappingConfirm(company,text(preview,"request_key"),"tester"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM oms_carrier_mapping WHERE company_code=?",Integer.class,company));}


    @Test void wmsDirectionIsDerivedForAllPurposesEvenIfClientOmitsOrForgesIt(){long a=number(standard("A"),"id");cap(a,"OUTBOUND",Collections.emptyList());cap(a,"INBOUND",Collections.emptyList());for(String purpose:Arrays.asList("WMS_OUTBOUND_CREATE","WMS_RETURN_CREATE","WMS_OUTBOUND_ACTUAL","WMS_RETURN_ACTUAL")){String direction=purpose.endsWith("_ACTUAL")?"IN":"OUT",code="TEST_"+purpose;Map<String,Object> scope=ctx("WMS",purpose,"");Map<String,Object> saved=mapping(scope,a,code,"IN".equals(direction)?"OUT":"BOTH",1,"");assertEquals(direction,saved.get("direction"));assertEquals("IN".equals(direction)?0:1,number(saved,"is_default"));saved.remove("direction");saved=service.save(company,"mapping",saved,"tester");assertEquals(direction,saved.get("direction"));Map<String,Object> lookup=new LinkedHashMap<>(scope);lookup.putAll(row("direction",direction,"standard_id",a,"external_code",code,"owner_code","O1","real_store_code","R1","province","北京"));assertTrue(Boolean.TRUE.equals(service.convert(company,lookup).get("available")));lookup.put("direction","IN".equals(direction)?"OUT":"IN");assertEquals("INVALID_CONTEXT",service.convert(company,lookup).get("state"));}}
    @Test void wmsBatchPreviewAndConfirmationPersistThePurposeDirection(){long a=number(standard("A"),"id");for(String purpose:Arrays.asList("WMS_OUTBOUND_CREATE","WMS_RETURN_ACTUAL")){Map<String,Object> scope=ctx("WMS",purpose,"");Map<String,Object> d=new LinkedHashMap<>(scope);d.putAll(row("revision",0,"enabled",1,"external_code","TEST_BATCH_"+purpose,"external_name","TEST","evidence","TEST confirmed"));d=service.save(company,"directory",d,"tester");Map<String,Object> batch=new LinkedHashMap<>(scope);batch.putAll(row("evidence","TEST human confirmation","rows",Arrays.asList(row("directory_id",d.get("id"),"standard_id",a,"direction","BOTH","is_default",1,"enabled",1,"product_code",""))));Map<String,Object> preview=service.mappingPreview(company,batch,"tester");assertEquals(0,number(preview,"errors"));Map<String,Object> normalized=(Map<String,Object>)((List<Map<String,Object>>)preview.get("rows")).get(0).get("data");String direction=purpose.endsWith("_ACTUAL")?"IN":"OUT";assertEquals(direction,normalized.get("direction"));assertEquals("IN".equals(direction)?0:1,number(normalized,"is_default"));service.mappingConfirm(company,text(preview,"request_key"),"tester");assertEquals(direction,db.queryForObject("SELECT direction FROM oms_carrier_mapping WHERE company_code=? AND purpose=?",String.class,company,purpose));}}
    @Test void forgedInputDirectionCannotBypassWmsOutputDefaultUniqueness(){long a=number(standard("A"),"id");Map<String,Object> scope=ctx("WMS","WMS_OUTBOUND_CREATE","");List<Map<String,Object>> rows=new ArrayList<>();for(String code:Arrays.asList("TEST_X","TEST_Y")){Map<String,Object> d=new LinkedHashMap<>(scope);d.putAll(row("revision",0,"enabled",1,"external_code",code,"external_name",code,"evidence","TEST confirmed"));d=service.save(company,"directory",d,"tester");rows.add(row("directory_id",d.get("id"),"standard_id",a,"direction","IN","is_default",1,"enabled",1,"product_code",""));}Map<String,Object> batch=new LinkedHashMap<>(scope);batch.putAll(row("evidence","TEST confirmed","rows",rows));Map<String,Object> preview=service.mappingPreview(company,batch,"tester");assertEquals(1,number(preview,"errors"));assertThrows(IllegalArgumentException.class,()->service.mappingConfirm(company,text(preview,"request_key"),"tester"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM oms_carrier_mapping WHERE company_code=?",Integer.class,company));}

    @Test void channelActionsDeriveDirectionsAndRejectWrongRuntimeDirection(){long a=number(standard("A"),"id");for(String purpose:Arrays.asList("CHANNEL_SHIPPING","CHANNEL_EXCHANGE_LOGISTICS","CHANNEL_RETURN_IDENTIFY","CHANNEL_RETURN_BACKFILL")){boolean incoming=purpose.equals("CHANNEL_RETURN_IDENTIFY");String code="TEST_"+purpose;Map<String,Object> scope=ctx("CHANNEL",purpose,"");Map<String,Object> saved=mapping(scope,a,code,"BOTH",1,"");assertEquals(incoming?"IN":"OUT",saved.get("direction"));assertEquals(incoming?0:1,number(saved,"is_default"));Map<String,Object> request=new LinkedHashMap<>(scope);request.putAll(row("standard_id",a,"external_code",code,"direction",incoming?"IN":"OUT"));assertTrue(Boolean.TRUE.equals(service.convert(company,request).get("available")));request.put("direction",incoming?"OUT":"IN");assertEquals("INVALID_CONTEXT",service.convert(company,request).get("state"));}assertThrows(IllegalArgumentException.class,()->service.scope(ctx("CHANNEL","CHANNEL_RETURN_LOGISTICS","TEST")));}
    @Test void buyerReturnIdentificationCannotBeBorrowedForPlatformBackfill(){long a=number(standard("A"),"id"),b=number(standard("B"),"id");Map<String,Object> identify=ctx("CHANNEL","CHANNEL_RETURN_IDENTIFY","");mapping(identify,a,"001/platform.a","BOTH",1,"");Map<String,Object> target=ctx("CHANNEL","CHANNEL_RETURN_BACKFILL","");target.putAll(row("standard_id",a,"direction","OUT"));assertEquals("MISSING",service.convert(company,target).get("state"));mapping(target,b,"001/platform.a","BOTH",1,"");assertEquals(a,number(service.convert(company,ctx("CHANNEL","CHANNEL_RETURN_IDENTIFY","001/platform.a")),"standard_id"));target.put("standard_id",b);assertEquals("001/platform.a",service.freeze(company,"TEST_BACKFILL",target,"tester").get("external_code"));}
    @Test void preferredCandidatesAreExactScopeProductAndTenantBounded(){long a=number(standard("A"),"id");Map<String,Object> scope=ctx("CHANNEL","CHANNEL_RETURN_BACKFILL","");Map<String,Object> saved=mapping(scope,a,"TEST_DEFAULT","OUT",1,"");mapping(scope,a,"TEST_FAST","OUT",0,"FAST");Map<String,Object> shop=new LinkedHashMap<>(scope);shop.put("shop_id","7");mapping(shop,a,"TEST_SHOP","OUT",1,"");Map<String,Object> input=new LinkedHashMap<>(scope);input.put("items",Arrays.asList(row("id",0,"standard_id",a,"product_code",""),row("id",saved.get("id"),"standard_id",a,"product_code",""),row("id",0,"standard_id",a,"product_code","FAST")));List<Map<String,Object>> options=(List<Map<String,Object>>)service.outputOptions(company,input).get("rows");assertEquals(1,number(options.get(0),"other_count"));assertEquals("TEST_DEFAULT",options.get(0).get("default_code"));assertEquals(0,number(options.get(1),"other_count"));assertEquals(1,number(options.get(2),"other_count"));List<Map<String,Object>> other=(List<Map<String,Object>>)service.outputOptions("OTHER",input).get("rows");assertEquals(0,number(other.get(0),"other_count"));input.put("items",Collections.nCopies(101,row("standard_id",a)));assertThrows(IllegalArgumentException.class,()->service.outputOptions(company,input));input.put("purpose","CHANNEL_RETURN_IDENTIFY");assertThrows(IllegalArgumentException.class,()->service.outputOptions(company,input));}

    @Test void directoryAssociationFiltersUseTenantScopedTotalsAndPageAggregates(){
        long a=number(standard("UI_A"),"id"),b=number(standard("UI_B"),"id");Map<String,Object> scope=ctx("CHANNEL","CHANNEL_SHIPPING","");
        Map<String,Object> linked=mapping(scope,a,"UI_LINKED","OUT",1,""),disabled=mapping(scope,b,"UI_DISABLED","OUT",1,"");disabled.putAll(row("enabled",0,"disabled_reason","暂停"));service.save(company,"mapping",disabled,"tester");
        Map<String,Object> draft=new LinkedHashMap<>(scope);draft.putAll(row("revision",0,"external_code","UI_EMPTY","external_name","未关联","enabled",1,"evidence","正式清单"));service.save(company,"directory",draft,"tester");
        for(String state:Arrays.asList("UNLINKED","LINKED","DISABLED")){Map<String,String> q=new HashMap<>();q.put("association_state",state);q.put("pageSize","1");Map<String,Object> page=service.page(company,"directory",q);assertEquals(1,number(page,"total"));Map<?,?> first=(Map<?,?>)((List<?>)page.get("rows")).get(0);assertEquals(state,first.get("association_state"));}
        Map<String,String> q=new HashMap<>();q.put("directory_id",String.valueOf(linked.get("directory_id")));q.put("enabled","1");assertEquals(1,number(service.page(company,"mapping",q),"total"));assertEquals(0,number(service.page("OTHER","directory",Collections.emptyMap()),"total"));
        Map<String,Object> standard=service.configuration(company,"standard",a);standard.putAll(row("enabled",0,"disabled_reason","主体暂停"));service.save(company,"standard",standard,"tester");
        assertEquals(0,number(service.page(company,"directory",Collections.singletonMap("association_state","LINKED")),"total"));assertEquals(2,number(service.page(company,"directory",Collections.singletonMap("association_state","DISABLED")),"total"));
    }
